typedef struct {
    int node;
    int next;
} Entry;

int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int lower_bound_idx(int arr[], int n, int val) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) / 2;
        if (arr[m] < val) l = m + 1;
        else r = m;
    }
    return l;
}

