    xsArr[xcnt++] = Xf;
    ysArr[ycnt++] = Yi;
    ysArr[ycnt++] = Yf;

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d %d", &rx1[i], &ry1[i], &rx2[i], &ry2[i]);

