    }

    if (ny > 1) {
        for (int i = 0; i < nx; i++) {
            memset(diff, 0, (size_t)ny * sizeof(int));
            int xv = xsArr[i];

            for (int k = 0; k < N; k++) {
                if (rx1[k] <= xv && xv <= rx2[k]) {
                    int l = yL[k];
                    int r = yR[k];
                    if (l < r) {
                        diff[l]++;
                        diff[r]--;
                    }
                }
            }

            int cur = 0;
            unsigned char *col = vcov + (size_t)i * (ny - 1);

            for (int j = 0; j < ny - 1; j++) {
                cur += diff[j];
                col[j] = (cur > 0);
            }
        }
    }

    free(diff);

    int V = nx * ny;

    int *dist = (int *)malloc((size_t)V * sizeof(int));
    memset(dist, 0x3f, (size_t)V * sizeof(int));
    dist[start] = 0;

    int *head = (int *)malloc((size_t)(upper + 1) * sizeof(int));
    for (int i = 0; i <= upper; i++) head[i] = -1;

    size_t entryCap = (size_t)4 * V + 10;
    Entry *entries = (Entry *)malloc(entryCap * sizeof(Entry));
    size_t entryCnt = 0;

    entries[entryCnt].node = start;
    entries[entryCnt].next = head[0];
    head[0] = (int)entryCnt++;

    int answer = upper;
    int found = 0;
    int current = 0;

    while (current <= upper && !found) {
        while (head[current] != -1) {
            int idx = head[current];
            head[current] = entries[idx].next;

            int u = entries[idx].node;

            if (dist[u] != current) continue;

            if (u == target) {
                answer = current;
                found = 1;
                break;
            }

            int row = u / nx;
            int col = u - row * nx;

            if (col + 1 < nx) {
                int cost = hcov[(size_t)row * (nx - 1) + col]
                               ? 0
                               : xsArr[col + 1] - xsArr[col];
                int v = u + 1;
                int nd = current + cost;

                if (nd <= upper && nd < dist[v]) {
                    dist[v] = nd;
                    entries[entryCnt].node = v;
                    entries[entryCnt].next = head[nd];
                    head[nd] = (int)entryCnt++;
                }
            }

            if (col > 0) {
                int cost = hcov[(size_t)row * (nx - 1) + (col - 1)]
                               ? 0
                               : xsArr[col] - xsArr[col - 1];
                int v = u - 1;
                int nd = current + cost;

                if (nd <= upper && nd < dist[v]) {
                    dist[v] = nd;
                    entries[entryCnt].node = v;
                    entries[entryCnt].next = head[nd];
                    head[nd] = (int)entryCnt++;
                }
            }

            if (row + 1 < ny) {
                int cost = vcov[(size_t)col * (ny - 1) + row]
                               ? 0
                               : ysArr[row + 1] - ysArr[row];
                int v = u + nx;
                int nd = current + cost;

                if (nd <= upper && nd < dist[v]) {
                    dist[v] = nd;
                    entries[entryCnt].node = v;
                    entries[entryCnt].next = head[nd];
                    head[nd] = (int)entryCnt++;
                }
            }

            if (row > 0) {
                int cost = vcov[(size_t)col * (ny - 1) + (row - 1)]
                               ? 0
                               : ysArr[row] - ysArr[row - 1];
                int v = u - nx;
                int nd = current + cost;

                if (nd <= upper && nd < dist[v]) {
                    dist[v] = nd;
                    entries[entryCnt].node = v;
                    entries[entryCnt].next = head[nd];
                    head[nd] = (int)entryCnt++;
                }
            }
        }

        if (!found) current++;
    }

    if (!found) answer = dist[target];

    printf("%d\n", answer);

    free(hcov);
    free(vcov);
    free(dist);
    free(head);
    free(entries);

    return 0;
}
